ALPHABET = frozenset(range(32, 127))
RESERVED = frozenset(b'.[]()|*+?\\^${}')
CLASS_RESERVED = frozenset(b'[]\\-^')

class InvalidInput(ValueError):
    pass

def parse(pattern, flags='NONE'):
